B.abS=new A.bP("Den\xe1r",!1,B.aIr,"St\u0159\xedbrn\xe1 \u0159\xedmsk\xe1 mince velk\xe1 asi jako dne\u0161n\xed desetikoruna. Byla to obvykl\xe1 denn\xed mzda d\u011bln\xedka na vinici \u2013 tedy \u201epen\xedze za jeden den pr\xe1ce\u201c.")
B.aBh=s(["peniz","penizi"],t.s)
B.abd=new A.bP("Den\xe1r (pen\xedz)",!0,B.aBh,"V Kralick\xe9 \u201epen\xedz\u201c v evangeli\xedch znamen\xe1 den\xe1r \u2013 st\u0159\xedbrnou \u0159\xedmskou minci s c\xedsa\u0159ov\xfdm obrazem, denn\xed mzdu d\u011bln\xedka.")
B.aps=s(["drachm*","gros","grose","grosu","grosi","grosem"],t.s)
B.abi=new A.bP("Drachma (gro\u0161)",!1,B.aps,"\u0158eck\xe1 st\u0159\xedbrn\xe1 mince v hodnot\u011b zhruba jednoho den\xe1ru \u2013 asi denn\xed mzda. Ztracen\xfd gro\u0161 v Lk 15 byl pro chudou \u017eenu velk\xe1 ztr\xe1ta.")
B.auT=s(["hrivn*"],t.s)
B.abB=new A.bP("H\u0159ivna",!1,B.auT,"Velk\xe1 jednotka v\xe1hy a pen\u011bz. Podle p\u0159ekladu ozna\u010duje bu\u010f minu (asi 100 den\xe1r\u016f, tedy t\u0159i a\u017e \u010dty\u0159i m\u011bs\xedce pr\xe1ce), nebo talent (p\u0159es 6000 den\xe1r\u016f \u2013 mzda za mnoho let).")
B.ano=s(["talent*"],t.s)
B.abD=new A.bP("Talent",!1,B.ano,"Nejv\u011bt\u0161\xed jednotka v\xe1hy a pen\u011bz: asi 30\u201340 kg st\u0159\xedbra, tedy zhruba 6000 den\xe1r\u016f \u2013 mzda za 15\u201320 let pr\xe1ce. Z podobenstv\xed o talentech poch\xe1z\xed i dne\u0161n\xed slovo \u201etalent\u201c pro nad\xe1n\xed.")
B.ayO=s(["mina","miny","minu","minami"],t.s)
B.abg=new A.bP("Mina",!1,B.ayO,"Jednotka v\xe1hy a pen\u011bz: asi p\u016fl kila st\u0159\xedbra, 100 den\xe1r\u016f \u2013 mzda za t\u0159i a\u017e \u010dty\u0159i m\u011bs\xedce.")
B.ajX=s(["sekel*","sekl*","sikl*"],t.s)
B.ab2=new A.bP("\u0160ekel",!1,B.ajX,"Z\xe1kladn\xed jednotka v\xe1hy (asi 11 g). Ve Star\xe9m z\xe1kon\u011b se neplatilo mincemi, ale odv\xe1\u017een\xfdm st\u0159\xedbrem \u2013 proto \u201e\u0161ekel\u201c znamen\xe1 v\xe1hu i cenu.")
B.aIj=s(["sarty","sart","sartu","halir","halire","lepto*","kodrant*"],t.s)
B.abH=new A.bP("Nejmen\u0161\xed mince",!1,B.aIj,"Lept\xf3n byla nejmen\u0161\xed m\u011bd\u011bn\xe1 mince v ob\u011bhu \u2013 asi 1/128 den\xe1ru. Dv\u011b takov\xe9 mince vdovy byly prakticky nic, a p\u0159ece podle Je\u017e\xed\u0161e dala nejv\xedc.")
B.ahW=s(["stater*"],t.s)
B.ab1=new A.bP("Stat\xe9r",!1,B.ahW,"St\u0159\xedbrn\xe1 mince v hodnot\u011b \u010dty\u0159 drachem \u2013 p\u0159esn\u011b chr\xe1mov\xe1 da\u0148 za dva lidi (Petra a Je\u017e\xed\u0161e, Mt 17,27).")
B.ar0=s(["clo","cla","clu","cle","celnic*"],t.s)
B.abn=new A.bP("Clo a dan\u011b",!1,B.ar0,"\u0158\xedman\xe9 pronaj\xedmali v\xfdb\u011br cel a dan\xed m\xedstn\xedm lidem. Ti museli odv\xe9st pevnou \u010d\xe1stku a co vybrali nav\xedc, si nechali \u2013 proto byli celn\xedci pova\u017eov\xe1ni za zlod\u011bje a zr\xe1dce.")
B.apW=s(["loket","lokte","loktu","lokty","loktech","loktu","loktum"],t.s)
B.ac_=new A.bP("Loket",!1,B.apW,"D\xe9lkov\xe1 m\xedra od lokte po konec prost\u0159edn\xed\u010dku \u2013 asi 45 cm. Goli\xe1\u0161 m\u011b\u0159il \u201e\u0161est loket a p\xed\u010f\u201c, tedy kolem t\u0159\xed metr\u016f (podle jin\xfdch rukopis\u016f asi dva metry).")
B.aBr=s(["pid","pidi","pidem"],t.s)
B.abf=new A.bP("P\xed\u010f",!1,B.aBr,"Rozp\u011bt\xed rozta\u017een\xe9 dlan\u011b od palce po mal\xed\u010dek \u2013 asi 22 cm, p\u016fl lokte.")
B.asf=s(["efa","efy","efu","efi","efou"],t.s)
B.abO=new A.bP("Efa",!1,B.asf,"Dut\xe1 m\xedra na obil\xed a mouku, asi 22 litr\u016f \u2013 zhruba velk\xfd kbel\xedk. Desetina efy (omer) byla denn\xed d\xe1vka many na osobu.")
B.amz=s(["chomer*","chomeru"],t.s)
B.abV=new A.bP("Chomer a k\xf3r",!1,B.amz,"Velk\xe1 m\xedra na obil\xed \u2013 \u201eosl\xed n\xe1klad\u201c, asi 220 litr\u016f. Odpov\xedd\xe1 deseti ef\xe1m.")
B.aqR=s(["bat","batu","batu","batech"],t.s)
B.abI=new A.bP("Bat",!1,B.aqR,"M\xedra na tekutiny (olej, v\xedno), asi 22 litr\u016f \u2013 stejn\u011b jako efa u obil\xed.")
B.avX=s(["hin","hinu"],t.s)
B.abJ=new A.bP("Hin",!1,B.avX,"Men\u0161\xed m\xedra na tekutiny, asi 3,5\u20134 litry.")
B.anF=s(["stadi*"],t.s)
B.aaZ=new A.bP("Stadium",!1,B.anF,"\u0158eck\xe1 d\xe9lkov\xe1 m\xedra, asi 185 metr\u016f \u2013 d\xe9lka b\u011b\u017eeck\xe9 dr\xe1hy na stadionu. Odtud dne\u0161n\xed slovo stadion.")
B.aif=s(["farize*","farizej*"],t.s)
B.abR=new A.bP("Farizeov\xe9",!1,B.aif,"Zbo\u017en\xe9 hnut\xed laik\u016f, kte\u0159\xed cht\u011bli zachov\xe1vat Z\xe1kon v ka\u017edodenn\xedm \u017eivot\u011b \u2013 p\u0159i j\xeddle, pr\xe1ci i sabatu. Lid si jich v\xe1\u017eil. Je\u017e\xed\u0161 je kritizoval, kdy\u017e se pravidla stala d\u016fle\u017eit\u011bj\u0161\xed ne\u017e milosrdenstv\xed.")
B.ah7=s(["saduce*","saducej*"],t.s)
B.aaW=new A.bP("Saduceov\xe9",!1,B.ah7,"Kn\u011b\u017esk\xe1 aristokracie kolem chr\xe1mu, spolupracovala s \u0158\xedmany. Uzn\xe1vali jen p\u011bt knih Moj\u017e\xed\u0161ov\xfdch a nev\u011b\u0159ili ve vzk\u0159\xed\u0161en\xed ani v and\u011bly.")
B.anY=s(["zakonik*","zakonic*"],t.s)
B.abY=new A.bP("Z\xe1kon\xedci",!1,B.anY,"Znalci a vyklada\u010di Z\xe1kona \u2013 u\u010ditel\xe9 a \u201epr\xe1vn\xedci\u201c sv\xe9 doby. Opisovali P\xedsmo a rozhodovali, jak se m\xe1 p\u0159ik\xe1z\xe1n\xed v praxi dodr\u017eovat.")
B.ah2=s(["publikan*","celnik*"],t.s)
B.ab0=new A.bP("Celn\xedci (publik\xe1ni)",!1,B.ah2,"V\xfdb\u011br\u010d\xed cel a dan\xed pro \u0158\xedmany. \u010casto vyb\xedrali v\xedc, ne\u017e m\u011bli \u2013 lid je pokl\xe1dal za podvodn\xedky a kolaboranty. Je\u017e\xed\u0161 s nimi p\u0159esto jedl a jednoho (Matou\u0161e) povolal za u\u010dedn\xedka.")
B.avY=s(["levit*"],t.s)
B.abo=new A.bP("Levit\xe9",!1,B.avY,"Potomci L\xe9viho, kmene ur\u010den\xe9ho ke slu\u017eb\u011b ve svatyni. Pom\xe1hali kn\u011b\u017e\xedm, starali se o chr\xe1m, zp\u011bv a str\xe1\u017e. Nedostali vlastn\xed \xfazem\xed, \u017eili z des\xe1tk\u016f.")
B.aky=s(["samar*","samaritan*"],t.s)
B.abT=new A.bP("Sama\u0159\xed a Samarit\xe1ni",!1,B.aky,"Obyvatel\xe9 st\u0159edn\xed \u010d\xe1sti zem\u011b, potomci Izraelc\u016f sm\xed\u0161en\xfdch s jin\xfdmi n\xe1rody. Uct\xedvali Boha na ho\u0159e Gerizim a uzn\xe1vali jen T\xf3ru. \u017did\xe9 a Samarit\xe1ni se navz\xe1jem nesn\xe1\u0161eli \u2013 proto byl \u201emilosrdn\xfd Samarit\xe1n\u201c tak \u0161okuj\xedc\xed.")
B.awT=s(["velerad*","sanhedr*"],t.s)
B.abX=new A.bP("Velerada",!1,B.awT,"Nejvy\u0161\u0161\xed \u017eidovsk\xfd soud v Jeruzal\xe9m\u011b \u2013 71 \u010dlen\u016f v \u010dele s velekn\u011bzem. Za \u0158\xedman\u016f rozhodovala o n\xe1bo\u017eensk\xfdch v\u011bcech, ale trest smrti vyn\xe9st nesm\u011bla.")
B.aou=s(["velekn*"],t.s)
B.ab6=new A.bP("Velekn\u011bz",!1,B.aou,"Nejvy\u0161\u0161\xed kn\u011bz Izraele. Jen on sm\u011bl jednou za rok, o Dni sm\xed\u0159en\xed, vstoupit do velesvatyn\u011b. Za Je\u017e\xed\u0161e \xfa\u0159ad obsazovali \u0158\xedman\xe9 a Herodes.")
B.app=s(["setnik*"],t.s)
B.abN=new A.bP("Setn\xedk",!1,B.app,"\u0158\xedmsk\xfd d\u016fstojn\xedk vel\xedc\xed asi stovce voj\xe1k\u016f (centurio). Setn\xedci jsou v Nov\xe9m z\xe1kon\u011b \u010dasto vyl\xed\u010deni kladn\u011b \u2013 jeden z nich vyznal pod k\u0159\xed\u017eem: \u201eTento byl Syn Bo\u017e\xed.\u201c")
B.ax8=s(["prokurator*","mistodrzi*"],t.s)
B.ac4=new A.bP("M\xedstodr\u017eitel",!1,B.ax8,"\u0158\xedmsk\xfd spr\xe1vce provincie (Pil\xe1t v Judsku). M\u011bl vojsko, vyb\xedral dan\u011b a jako jedin\xfd mohl vyn\xe9st rozsudek smrti.")
B.anP=s(["ctvrtak*","tetrarch*"],t.s)
B.abP=new A.bP("Tetrarcha (\u010dtvrt\xe1k)",!1,B.anP,"Doslova \u201evl\xe1dce \u010dtvrtiny\u201c \u2013 men\u0161\xed panovn\xedk z\xe1visl\xfd na \u0158\xedmu. Herodes Antipas, kter\xfd dal popravit Jana K\u0159titele, byl tetrarchou Galileje.")
B.aI9=s(["vdov*","sirot*"],t.s)
B.abZ=new A.bP("Vdovy a sirotci",!1,B.aI9,"Ve spole\u010dnosti bez soci\xe1ln\xedho syst\xe9mu byli nejzraniteln\u011bj\u0161\xed: nem\u011bli mu\u017ee ani otce, kter\xfd by je \u017eivil a h\xe1jil. Z\xe1kon i proroci proto opakovan\u011b volaj\xed po jejich ochran\u011b.")
B.aiT=s(["otrok*","otrokyn*"],t.s)
B.abp=new A.bP("Otroci",!1,B.aiT,"Otroctv\xed bylo ve starov\u011bku b\u011b\u017en\xe9 \u2013 z dluh\u016f, v\xe1lek nebo narozen\xedm. Izraelsk\xfd z\xe1kon ho omezoval (propu\u0161t\u011bn\xed po \u0161esti letech), v \u0159\xedmsk\xe9m sv\u011bt\u011b tvo\u0159ili otroci velkou \u010d\xe1st obyvatel.")
B.aCh=s(["pastyr*","pastucha*"],t.s)
B.abC=new A.bP("Past\xfd\u0159",!1,B.aCh,"Past\xfd\u0159 vodil ovce na pastvu, hledal vodu a v noci je chr\xe1nil p\u0159ed \u0161elmami a zlod\u011bji. Ovce znaly jeho hlas. Proto se \u201epast\xfd\u0159\u201c stal obrazem kr\xe1le i Boha.")
B.alY=s(["tesar*"],t.s)
B.abA=new A.bP("Tesa\u0159",!1,B.alY,"\u0158eck\xe9 slovo tekt\xf3n znamen\xe1 \u0159emesln\xedka, kter\xfd pracuje se d\u0159evem i kamenem \u2013 sp\xed\u0161 \u201estavitel\u201c. Je\u017e\xed\u0161 i Josef tak \u017eivili rodinu.")
B.ahl=s(["sabat*","sobot*"],t.s)
B.ac3=new A.bP("Sabat (sobota)",!1,B.ahl,"Sedm\xfd den t\xfddne, den odpo\u010dinku od p\xe1te\u010dn\xedho do sobotn\xedho ve\u010dera. Nesm\u011blo se pracovat ani cestovat d\xe1l ne\u017e asi kilometr. P\u0159ipom\xednal stvo\u0159en\xed i vysvobozen\xed z otroctv\xed.")
B.az6=s(["velikonoc*","pesach*","fase","fasy","fasu"],t.s)
B.abl=new A.bP("Pesach (Velikonoce)",!1,B.az6,"Sv\xe1tek vysvobozen\xed z Egypta. Ka\u017ed\xe1 rodina jedla ber\xe1nka, nekva\u0161en\xfd chl\xe9b a ho\u0159k\xe9 byliny a vypr\xe1v\u011bla p\u0159\xedb\u011bh exodu. Do Jeruzal\xe9ma tehdy p\u0159i\u0161ly statis\xedce poutn\xedk\u016f.")
B.apk=s(["letnic*"],t.s)
B.abL=new A.bP("Letnice",!1,B.apk,"Sv\xe1tek \u017en\xed pades\xe1t dn\xed po Pesachu (\u0159ecky Pent\xe9kost\xe9 \u2013 \u201epades\xe1t\xfd\u201c). Do chr\xe1mu se nesly prvn\xed chleby z nov\xe9 \xfarody.")
B.akK=s(["nekvasen*","presnic*","presnych","presny"],t.s)
B.ab9=new A.bP("Nekva\u0161en\xfd chl\xe9b",!1,B.akK,"Ploch\xfd chl\xe9b bez kvasu, upe\u010den\xfd narychlo. O Pesachu p\u0159ipom\xednal, \u017ee Izrael odch\xe1zel z Egypta ve sp\u011bchu a t\u011bsto nestihlo vykynout.")
B.agL=s(["kvas","kvasu","kvasem","kvasne","kvasny"],t.s)
B.ab7=new A.bP("Kvas",!1,B.agL,"Kousek star\xe9ho zkva\u0161en\xe9ho t\u011bsta, kter\xfd se p\u0159id\xe1val do nov\xe9ho. Mal\xe9 mno\u017estv\xed prokvas\xed v\u0161echno \u2013 proto je kvas obrazem tich\xe9ho r\u016fstu (Bo\u017e\xed kr\xe1lovstv\xed) i \u0161\xed\u0159en\xed zla.")
B.am4=s(["obriz*","obrez*"],t.s)
B.abj=new A.bP("Ob\u0159\xedzka",!1,B.am4,"Znamen\xed smlouvy s Abrahamem, prov\xe1d\u011bn\xe9 chlapc\u016fm osm\xfd den po narozen\xed. V prvn\xed c\xedrkvi se vedl velk\xfd spor, zda mus\xed b\xfdt ob\u0159ez\xe1ni i pohan\xe9 (Sk 15).")
B.aj1=s(["desatek","desatk*","desatky"],t.s)
B.abz=new A.bP("Des\xe1tek",!1,B.aj1,"Desetina \xfarody a st\xe1da odevzd\xe1van\xe1 Bohu \u2013 na podporu levit\u016f, kn\u011b\u017e\xed, chud\xfdch, vdov a cizinc\u016f.")
B.ate=s(["malomoc*"],t.s)
B.abh=new A.bP("Malomocenstv\xed",!1,B.ate,"Souhrnn\xe9 ozna\u010den\xed pro r\u016fzn\xe9 ko\u017en\xed nemoci (nejen dne\u0161n\xed lepru). Nemocn\xfd musel \u017e\xedt mimo obec a volat \u201ene\u010dist\xfd!\u201c. Je\u017e\xed\u0161\u016fv dotek malomocn\xe9ho byl proto n\u011b\u010d\xedm nev\xeddan\xfdm.")
B.aFt=s(["pomaz*"],t.s)
B.abW=new A.bP("Pomaz\xe1n\xed",!1,B.aFt,"Polit\xed hlavy olejem p\u0159i dosazen\xed kr\xe1le, kn\u011bze nebo proroka \u2013 znamen\xed, \u017ee ho vybral B\u016fh. Hebrejsky \u201epomazan\xfd\u201c = ma\u0161\xedach, Mesi\xe1\u0161; \u0159ecky Christos.")
B.au9=s(["nazir*"],t.s)
B.ab5=new A.bP("Naz\xedrsk\xfd slib",!1,B.au9,"Zvl\xe1\u0161tn\xed zasv\u011bcen\xed Bohu: nest\u0159\xedhat si vlasy, nep\xedt v\xedno a nedot\xfdkat se mrtv\xfdch. Naz\xedrem byl nap\u0159\xedklad Samson.")
B.aBo=s(["prvoroz*"],t.s)
B.abx=new A.bP("Prvorozenstv\xed",!1,B.aBo,"Nejstar\u0161\xed syn dost\xe1val dvojn\xe1sobn\xfd pod\xedl d\u011bdictv\xed a veden\xed rodu. Proto tolik z\xe1le\u017eelo na tom, komu otec po\u017eehn\xe1 (Ezau a J\xe1kob).")
B.aoI=s(["paberk*"],t.s)
B.aby=new A.bP("Pab\u011brkov\xe1n\xed",!1,B.aoI,"Z\xe1kon p\u0159ikazoval neskl\xedzet pole a\u017e do kraj\u016f a nechat na n\u011bm klasy, kter\xe9 spadly \u2013 pro chud\xe9, vdovy a cizince. Tak se \u017eivila R\xfat na B\xf3azov\u011b poli.")
B.aiL=s(["zapaln*"],t.s)
B.abr=new A.bP("Z\xe1paln\xe1 ob\u011b\u0165",!1,B.aiL,"Ob\u011b\u0165, p\u0159i kter\xe9 se cel\xe9 zv\xed\u0159e sp\xe1lilo na olt\xe1\u0159i \u2013 vyjad\u0159ovala \xfapln\xe9 odevzd\xe1n\xed Bohu.")
B.aqO=s(["stanek","stanku","stankem","svatostan*"],t.s)
