B.aI3=s(["truhl*"],t.s)
B.abG=new A.bP("Truhla smlouvy",!1,B.aI3,"Pozlacen\xe1 sk\u0159\xed\u0148ka asi 110 \xd7 70 \xd7 70 cm s deskami Desatera. V\xedko se dv\u011bma cheruby (\u201eslitovnice\u201c) bylo m\xedstem Bo\u017e\xed p\u0159\xedtomnosti.")
B.ajN=s(["efod*"],t.s)
B.abK=new A.bP("Efod",!1,B.ajN,"Kn\u011b\u017esk\xe9 roucho podobn\xe9 z\xe1st\u011b\u0159e, u velekn\u011bze zdoben\xe9 zlatem a drahokamy. Pat\u0159il k n\u011bmu n\xe1prsn\xedk s urim a tumim.")
B.ahg=s(["urim*","tumim*"],t.s)
B.abw=new A.bP("Urim a tumim",!1,B.ahg,"P\u0159edm\u011bty v n\xe1prsn\xedku velekn\u011bze, jimi\u017e se hledala Bo\u017e\xed odpov\u011b\u010f ano/ne. Jak p\u0159esn\u011b fungovaly, dnes nev\xedme.")
B.akc=s(["svicen*","svicn*","menor*"],t.s)
