B.al6=s(["kadid*"],t.s)
B.abQ=new A.bP("Kadidlo",!1,B.al6,"Vonn\xe1 prysky\u0159ice ze strom\u016f ji\u017en\xed Ar\xe1bie. Spalovala se na zlat\xe9m olt\xe1\u0159i \u2013 obraz modliteb stoupaj\xedc\xedch k Bohu. Byla velmi drah\xe1.")
B.avi=s(["synagog*"],t.s)
